mapper.select:
SELECT c.*, u.name AS username
FROM community_comment c
INNER JOIN user u ON c.user_id = u.user_id
WHERE c.post_id = #{postId}
ORDER BY c.comment_id DESC;

mapper.update:
UPDATE user_payment_history
SET review_status = 'y'
WHERE user_id = #{review.userId} AND class_id = #{review.classId}

mapper.select:
select c.*, f.file_url as fileUrl from class_lesson c
LEFT JOIN file f ON c.file_no = f.file_no
where section_id = #{sectionId}

mapper.update:
UPDATE community_post
SET title = #{title}, content = #{content}, created_at = NOW()
WHERE post_id = #{postId}

UPDATE community_comment
SET content = #{content}
WHERE comment_id = #{commentId}
